-- Row-level security for every tenant table (generated by scripts/gen-rls-migration.ts).
-- The application sets app.company_id per transaction (lib/prisma.ts); platform paths set app.bypass_rls.

CREATE OR REPLACE FUNCTION app_company_id() RETURNS uuid LANGUAGE sql STABLE AS $$
  SELECT NULLIF(current_setting('app.company_id', true), '')::uuid
$$;

CREATE OR REPLACE FUNCTION app_rls_bypass() RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT COALESCE(current_setting('app.bypass_rls', true), 'off') = 'on'
$$;

ALTER TABLE "SupplierMaterialPrice" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "SupplierMaterialPrice" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON "SupplierMaterialPrice";
CREATE POLICY tenant_isolation ON "SupplierMaterialPrice" USING (company_id = app_company_id()) WITH CHECK (company_id = app_company_id());
DROP POLICY IF EXISTS platform_bypass ON "SupplierMaterialPrice";
CREATE POLICY platform_bypass ON "SupplierMaterialPrice" USING (app_rls_bypass()) WITH CHECK (app_rls_bypass());

